export function unpackModelWeights(modelData) {
    // modelData is an array of 2 layers [L1, L2]
    // L1: 48 in -> 128 out (dense relu)
    // L2: 128 in -> 16 out (dense linear)
    
    function unpackLayer(layer) {
        const rawStr = atob(layer.data_b64);
        const rawBytes = new Uint8Array(rawStr.length);
        for (let i = 0; i < rawStr.length; i++) {
            rawBytes[i] = rawStr.charCodeAt(i);
        }
        
        const inCh = layer.in_ch;
        const outCh = layer.out_ch;
        const wScale = layer.weight_scale;
        const bScale = layer.bias_scale;
        
        const weights = new Float32Array(inCh * outCh);
        for (let y = 0; y < inCh; y++) {
            for (let j = 0; j < outCh; j++) {
                const b = rawBytes[y * outCh + j];
                weights[y * outCh + j] = ((b / 255.0) - 0.5) * wScale;
            }
        }
        
        const biases = new Float32Array(outCh);
        for (let j = 0; j < outCh; j++) {
            const b = rawBytes[inCh * outCh + j];
            biases[j] = ((b / 255.0) - 0.5) * bScale;
        }
        
        return { weights, biases, inCh, outCh };
    }
    
    const l1 = unpackLayer(modelData[0]);
    const l2 = unpackLayer(modelData[1]);
    
    // Pack into a single contiguous Float32Array for GPU buffer upload:
    // Layout:
    // [0 .. 6143]: W1 (48 * 128)
    // [6144 .. 6271]: B1 (128)
    // [6272 .. 8319]: W2 (128 * 16)
    // [8320 .. 8335]: B2 (16)
    // Total: 8336 floats
    const packed = new Float32Array(8336);
    packed.set(l1.weights, 0);
    packed.set(l1.biases, 6144);
    packed.set(l2.weights, 6272);
    packed.set(l2.biases, 8320);
    
    return { l1, l2, packed };
}

